		#region OPERATIONS

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static floatQ InvertedMultiply(in floatQ a, in floatQ b)
		{
            return new floatQ(
				(-a.x * b.w + b.x * a.w - a.y * b.z) + (a.z * b.y),
				(-a.y * b.w + b.y * a.w - a.z * b.x) + (a.x * b.z),
				(-a.z * b.w + b.z * a.w - a.x * b.y) + (a.y * b.x),
				(a.w * b.w) - (-a.x * b.x - a.y * b.y - a.z * b.z));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float3 InvertedMultiply(in floatQ q, in float3 v)
		{
			var x = q.x + q.x;
			var y = q.y + q.y;
			var z = q.z + q.z;
			var wx = -q.w * x;
			var wy = -q.w * y;
			var wz = -q.w * z;
			var xx = q.x * x;
			var xy = q.x * y;
			var xz = q.x * z;
			var yy = q.y * y;
			var yz = q.y * z;
			var zz = q.z * z;

			var num1 = ((1 - yy) - zz);
			var num2 = (xy - wz);
			var num3 = (xz + wy);
			var num4 = (xy + wz);
			var num5 = ((1 - xx) - zz);
			var num6 = (yz - wx);
			var num7 = (xz - wy);
			var num8 = (yz + wx);
			var num9 = ((1 - xx) - yy);

			return new float3(
				((v.x * num1) + (v.y * num2)) + (v.z * num3),
				((v.x * num4) + (v.y * num5)) + (v.z * num6),
				((v.x * num7) + (v.y * num8)) + (v.z * num9));
		}

		#endregion
	}

	// Extensions

	public static partial class MathX
	{
		
		public static floatQ ReflectRotation(in floatQ rotation, in float3 planeNormal)
		{
			// TODO!!! An optimized version, using Reflection Matrix?
			var forward = rotation * float3.Forward;
			var up = rotation * float3.Up;

			forward = MathX.ReflectVector(forward, planeNormal);
			up = MathX.ReflectVector(up, planeNormal);

			return floatQ.LookRotation(forward, up);
		}

		public static float AngleAroundAxis(floatQ rotation, float3 axis, float3? comparisonAxis = null)
		{
			float3 comparison;
			if(comparisonAxis != null)
				comparison = comparisonAxis.Value;
			else
				MathX.Orthonormals(axis, out comparison, out _);

			var rotated = rotation * comparison;

			// project both rotated and comparsion on the plane given by the axis and compute the angles they represent
			var toUp = floatQ.FromToRotation(axis, float3.Up);

			rotated = toUp * rotated;
			comparison = toUp * comparison;

			var rotatedAngle = MathX.Atan2(rotated.xz) * MathX.Rad2Deg;
			var comparisonAngle = MathX.Atan2(comparison.xz) * MathX.Rad2Deg;

			return MathX.DeltaAngle(comparisonAngle, rotatedAngle);
		}

		// Adapted from BEPUPhysics
		public static floatQ Slerp(in floatQ a, floatQ b, float lerp)
		{
			if(lerp <= 0)
				return a;
			if(lerp >= 1)
				return b;

			return SlerpUnclamped(a, b, lerp);
		}

        public static floatQ SlerpUnclamped(in floatQ a, floatQ b, float lerp)
		{
			float cosHalfTheta = a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z;

            if (cosHalfTheta < 0)
            {
                b = b.Negated;
                cosHalfTheta = -cosHalfTheta;
            }

            if (cosHalfTheta >= 1)
				return b;

            var halfTheta = MathX.Acos(cosHalfTheta);
            var sinHalfTheta = MathX.Sqrt(1 - cosHalfTheta * cosHalfTheta);

            var aFraction = MathX.Sin((1 - lerp) * halfTheta) / sinHalfTheta;
            var bFraction = MathX.Sin(lerp * halfTheta) / sinHalfTheta;

			return new floatQ(
				a.x * aFraction + b.x * bFraction,
				a.y * aFraction + b.y * bFraction,
				a.z * aFraction + b.z * bFraction,
				a.w * aFraction + b.w * bFraction
			);
		}

        public static floatQ BezierCurve(floatQ from, floatQ to, floatQ fromTangent, floatQ toTangent, float t)
        {
            var u = 1f - t;
            var tt = t * t;
            var uu = u * u;
            var ttt = tt * t;
            var uuu = uu * u;

            return (uuu * from +
                (3 * uu * t * fromTangent) +
                (3 * u * tt * toTangent) +
                ttt * to).Normalized;
        }

        public static floatQ BezierTangent(floatQ from, floatQ to, floatQ fromTangent, floatQ toTangent, float t)
        {
            return (-3f * MathX.Pow(1f - t, 2f) * from +
                3f * MathX.Pow(1f - t, 2f) * fromTangent -
                6f * t * (1f - t) * fromTangent -
                3f * MathX.Pow(t, 2f) * toTangent +
                6f * t * (1f - t) * toTangent +
                3f * MathX.Pow(t, 2f) * to).Normalized;
        }

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static floatQ Lerp(in floatQ a, in floatQ b, float lerp)
		{
			if(lerp <= 0)
				return a;
			if(lerp >= 1)
				return b;

			return new floatQ(a.x + (b.x - a.x) * lerp, a.y + (b.y - a.y) * lerp, a.z + (b.z - a.z) * lerp, a.w + (b.w - a.w) * lerp).FastNormalized;;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static floatQ LerpUnclamped(in floatQ a, in floatQ b, float lerp)
		{
			return new floatQ(a.x + (b.x - a.x) * lerp, a.y + (b.y - a.y) * lerp, a.z + (b.z - a.z) * lerp, a.w + (b.w - a.w) * lerp).FastNormalized;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Dot(in floatQ a, in floatQ b)
		{
			return a.x*b.x + a.y*b.y + a.z*b.z + a.w*b.w;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float AngleRad(in floatQ a, in floatQ b)
		{
			return MathX.Acos(MathX.Min(MathX.Abs(Dot(a,b)), 1)) * 2;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Angle(in floatQ a, in floatQ b)
		{
			return MathX.Acos(MathX.Min(MathX.Abs(Dot(a,b)), 1)) * 2 * MathX.Rad2Deg;
		}

		public static floatQ RotateTowards(in floatQ from, in floatQ to, float maxAngle)
		{
			var angle = MathX.Angle(from, to);

			if(angle == 0)
				return from;

			var ratio = MathX.Min(1, maxAngle / angle);
			return MathX.Slerp(from, to, ratio);
		}

        public static floatQ RotateByAngle(in floatQ from, in floatQ to, float rotationAngle)
		{
			var angle = MathX.Angle(from, to);

			if(angle == 0)
				return from;

			var ratio = rotationAngle / angle;
			return MathX.Slerp(from, to, ratio);
		}

		public static floatQ LimitSwing(in floatQ rotation, in float3 axis, float maxAngle)
		{
			if(axis == float3.Zero)
				return rotation;

			var targetAxis = rotation * axis;
			var targetRotation = floatQ.FromToRotation(axis, targetAxis);
			var limitedRotation = RotateTowards(floatQ.Identity, targetRotation, maxAngle);
			var limitedAxis = limitedRotation * axis;

			var fix = floatQ.FromToRotation(targetAxis, limitedAxis);

			return fix * rotation;
		}

        public static floatQ SetSwing(in floatQ rotation, in float3 axis, float swingAngle)
		{
			if(axis == float3.Zero)
				return rotation;

			var targetAxis = rotation * axis;
			var targetRotation = floatQ.FromToRotation(axis, targetAxis);
			var limitedRotation = RotateByAngle(floatQ.Identity, targetRotation, swingAngle);
			var limitedAxis = limitedRotation * axis;

			var fix = floatQ.FromToRotation(targetAxis, limitedAxis);

			return fix * rotation;
		}

		public static floatQ LimitTwist(in floatQ rotation, in float3 axis, 
			in float3 orthoAxis, float maxAngle)
		{
			if(maxAngle >= 180)
				return rotation;

			maxAngle = MathX.Clamp(maxAngle, 0, 180);

			var normal = rotation * axis;
			var orthoTangent = orthoAxis;
			MathX.Orthonormalize(ref normal, ref orthoTangent);

			var rotatedOrthoTangent = rotation * orthoAxis;
			MathX.Orthonormalize(ref normal, ref rotatedOrthoTangent);

			var fixedRotation = floatQ.FromToRotation(rotatedOrthoTangent, orthoTangent) * rotation;

			if(maxAngle == 0)
				return fixedRotation;

			return MathX.RotateTowards(fixedRotation, rotation, maxAngle);
		}

        // Based on: https://stackoverflow.com/questions/3684269/component-of-a-quaternion-rotation-around-an-axis
        public static void DecomposeSwingTwist(in floatQ rotation, in float3 axis,
            out floatQ swing, out floatQ twist)
        {
            var ra = rotation.xyz;
            var p = MathX.Project(ra, axis);
            
            twist = new floatQ(p.x, p.y, p.z, rotation.w);
            twist = twist.Normalized;

            swing = rotation * twist.Conjugated;
        }

        public static float AxisAngle(in floatQ rotation)
        {
            return 2 * MathX.Acos(rotation.w) * MathX.Rad2Deg;
        }

        public static void DecomposeAxisAngle(in floatQ rotation, out float3 axis, out float angle)
        {
            angle = 2 * MathX.Acos(rotation.w);
            var s = MathX.Sqrt(1-rotation.w*rotation.w);
            if(s == 0)
                axis = float3.Forward;
            else
                axis = rotation.xyz / s;

            angle *= MathX.Rad2Deg;
        }

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static floatQ Abs(in floatQ q)
		{
			return new floatQ(MathX.Abs(q.x), MathX.Abs(q.y), MathX.Abs(q.z), MathX.Abs(q.w));
		}

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static floatQ Pow(in floatQ q, float pow)
        {
            var angle = MathX.Acos(MathX.Clamp(q.w, -1, 1));
            var sinAngle = MathX.Sin(angle);

            if(MathX.Approximately(sinAngle, 0))
                return q;

            var unitVector = q.xyz / sinAngle;

            var newAngle = angle * pow;

            var newW = MathX.Cos(newAngle);
            var newV = unitVector * MathX.Sin(newAngle);

            return new floatQ(newV.x, newV.y, newV.z, newW);
        }

