	public static class FloatQExtensions
	{
		public static void Write(this BinaryWriter wr, in floatQ q)
		{
			wr.Write(q.x);
			wr.Write(q.y);
			wr.Write(q.z);
			wr.Write(q.w);
		}

		public static floatQ ReadSingleQ(this BinaryReader rd)
		{
			return new floatQ(
				rd.ReadSingle(),
				rd.ReadSingle(),
				rd.ReadSingle(),
				rd.ReadSingle()
			);
		}
	}

	
    [JsonObject(MemberSerialization = MemberSerialization.OptIn)]
	public readonly struct doubleQ : IEquatable<doubleQ>, IQuaternion<double>
	{
        public static readonly Type BASE_TYPE = typeof(double);

		public readonly double x, y, z, w;

        // Json serialization
        
            [JsonPropertyName("x")]
		    [JsonProperty(PropertyName = "x")]
		    [DebuggerBrowsable(DebuggerBrowsableState.Never)]
		    public readonly double X => x;

            
            [JsonPropertyName("y")]
		    [JsonProperty(PropertyName = "y")]
		    [DebuggerBrowsable(DebuggerBrowsableState.Never)]
		    public readonly double Y => y;

            
            [JsonPropertyName("z")]
		    [JsonProperty(PropertyName = "z")]
		    [DebuggerBrowsable(DebuggerBrowsableState.Never)]
		    public readonly double Z => z;

            
            [JsonPropertyName("w")]
		    [JsonProperty(PropertyName = "w")]
		    [DebuggerBrowsable(DebuggerBrowsableState.Never)]
		    public readonly double W => w;

            
        [JsonIgnore]
		public readonly Type ElementType => typeof(double);
		public readonly object GetBoxedElement(int n) => this[n];

		#region CONSTRUCTORS

        [System.Text.Json.Serialization.JsonConstructor]
	    [Newtonsoft.Json.JsonConstructor]
		public doubleQ(double x, double y, double z, double w)
		{
			this.x = x;
			this.y = y;
			this.z = z;
			this.w = w;
		}

		public readonly double this[int index]
		{
			get
			{
				switch(index)
				{
					case 0: return x;
					case 1: return y;
					case 2: return z;
					case 3: return w;
					default: throw new IndexOutOfRangeException("Invalid quaternion element index!");
				}
			}
		}

        public readonly double GetElement(int index) => this[index];

		public static doubleQ Identity => new doubleQ(0,0,0,1);
		public static doubleQ MinValue => new doubleQ(-1, -1, -1, -1);
		public static doubleQ MaxValue => new doubleQ(1, 1, 1, 1);

		#endregion

		#region PROPERTIES

        [JsonIgnore]
		public readonly double SqrMagnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => x*x + y*y + z*z + w*w;
		}

        [JsonIgnore]
		public readonly double Magnitude
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => MathX.Sqrt(SqrMagnitude);
		}

        [JsonIgnore]
		public readonly double AbsoluteSum
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get
			{
				var abs = MathX.Abs(this);
				return abs.x + abs.y + abs.z + abs.w;
			}
		}

        [JsonIgnore]
		public readonly doubleQ Normalized
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get
			{
				var inv = 1 / Magnitude;
				return this * inv;
			}
		}

        [JsonIgnore]
		public readonly doubleQ FastNormalized
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get
			{
				var sqrMag = SqrMagnitude;
				if(MathX.Abs(1 - sqrMag) < 2.107342e-08f)
					return this * (2f / (1f + sqrMag));
				else
					{
					var inv = 1 / MathX.Sqrt(SqrMagnitude);
					return this * inv;
				}
			}
		}

        [JsonIgnore]
		public readonly doubleQ SumNormalized
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get
			{
				var inv = 1 / AbsoluteSum;
				return this * inv;
			}
		}

        [JsonIgnore]
		public readonly doubleQ Filtered
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get
			{
				const float TOLERANCE = 1e-5f;

				return new doubleQ(
					MathX.Abs(x) < TOLERANCE ? 0 : x,
					MathX.Abs(y) < TOLERANCE ? 0 : y,
					MathX.Abs(z) < TOLERANCE ? 0 : z,
					MathX.Abs(w) < TOLERANCE ? 0 : w
				);
			}
		}

        [JsonIgnore]
		public readonly bool IsIdentity
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get
			{
				const float TOLERANCE = 1e-5f;
				return MathX.Abs(x) < TOLERANCE &&
					MathX.Abs(y) < TOLERANCE &&
					MathX.Abs(z) < TOLERANCE &&
					MathX.Abs(w-1) < TOLERANCE;
					
			}
		}

        [JsonIgnore]
		public readonly bool IsValid
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get
			{
				var mag = SqrMagnitude; 
				return mag > 0.9f && mag < 1.1f;
			}
		}

        [JsonIgnore]
		public readonly bool IsNaN
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => double.IsNaN(x)||double.IsNaN(y)||double.IsNaN(z)||double.IsNaN(w);
		}

        [JsonIgnore]
		public readonly bool IsInfinity 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => double.IsInfinity(x)||double.IsInfinity(y)||double.IsInfinity(z)||double.IsInfinity(w);
		}

        [JsonIgnore]
		public readonly doubleQ Negated
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
