		}

        [JsonIgnore]
		public readonly doubleQ Conjugated
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => new doubleQ(-x, -y, -z, w);
		}

        [JsonIgnore]
		public readonly doubleQ Inverted
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => Conjugated;
		}

