		#region CONVERSIONS AND GENERATORS

        [JsonIgnore]
		public readonly double3 EulerAngles => EulerAnglesRad * MathX.Rad2Deg;

        [JsonIgnore]
        public readonly double3 EulerAnglesRad => new double3(
					MathX.Asin(MathX.Clamp(2*(x*w - z*y), -1, 1)),
                    MathX.Atan2(2*(w*y + z*x), 1 - 2*(x*x + y*y)),
					MathX.Atan2(2*(y*x + z*w), 1 - 2*(x*x + z*z))
				) ;

		public static doubleQ AxisAngle(in double3 axis, double angle)
		{
			return AxisAngleRad(axis, angle * MathX.Deg2Rad);
		}

		public static doubleQ AxisAngleRad(double3 axis, double radians)
		{
			radians *= 0.5f;
			axis = axis.Normalized * MathX.Sin(radians);

			return new doubleQ(axis.x, axis.y, axis.z, MathX.Cos(radians));
		}

		public static doubleQ LookRotation(in double3 forward)
		{
			return LookRotation(forward, double3.Up);
		}

		// From: http://gamedev.stackexchange.com/questions/92419/how-to-get-quaternion-from-two-orthogonal-3d-vectors
		public static doubleQ LookRotation(in double3 forward, in double3 up)
		{
			if(forward == double3.Zero)
				return Identity;

			var m2 = forward.Normalized;
            var m0 = MathX.Cross(up, m2);
 
            // check for invalid result
            var m0sqr = m0.SqrMagnitude;
 
            // check for invalid result
            if (MathX.Approximately(m0sqr, 0f))
            {
                var altUp = AxisAngle(double3.Right, -90) * forward;
                m0 = MathX.Cross(altUp, m2);

                m0sqr = m0.SqrMagnitude;

                if(MathX.Approximately(m0sqr, 0f))
                {
                    altUp = AxisAngle(double3.Forward, 90) * forward;
                    m0 = MathX.Cross(altUp, m2);

                    m0sqr = m0.SqrMagnitude;
                }
            }

            // Normalize m0. We already computed the square magnitude
            // so we just do part of normalization here manually
            var m0mag = MathX.Sqrt(m0sqr);
            var invMag = 1 / m0mag;
            m0 *= invMag;			

			var m1 = MathX.Cross(m2, m0);			

			var r0 = m0.x + m1.y + m2.z;

			double x, y, z, w;

			if (r0 > 0)
			{
				var r1 = MathX.Sqrt(r0 + 1f);
				w = r1 * 0.5f;
				r1 = 0.5f / r1;
				x = (m1.z - m2.y) * r1;
				y = (m2.x - m0.z) * r1;
				z = (m0.y - m1.x) * r1;
			}
			else if((m0.x >= m1.y) && (m0.x >= m2.z))
			{
				var r1 = MathX.Sqrt(((1f + m0.x) - m1.y) - m2.z);
				var r2 = 0.5f / r1;
				x = 0.5f * r1;
				y = (m0.y + m1.x) * r2;
				z = (m0.z + m2.x) * r2;
				w = (m1.z - m2.y) * r2;
			}
			else if (m1.y > m2.z)
			{
				var r1 = MathX.Sqrt(((1f + m1.y) - m0.x) - m2.z);
				var r2 = 0.5f / r1;
				x = (m1.x + m0.y) * r2;
				y = 0.5f * r1;
				z = (m2.y + m1.z) * r2;
				w = (m2.x - m0.z) * r2;
			}
			else
			{
				var r1 = MathX.Sqrt(((1f + m2.z) - m0.x) - m1.y);
				var r2 = 0.5f / r1;
				x = (m2.x + m0.z) * r2;
				y = (m2.y + m1.z) * r2;
				z = 0.5f * r1;
				w = (m0.y - m1.x) * r2;
			}

			return new doubleQ(x,y,z,w);
		}

		public static doubleQ Euler(double x, double y, double z)
		{
			return Euler(new double3(x,y,z));
		}

        public static doubleQ EulerRad(double x, double y, double z)
		{
			return EulerRad(new double3(x,y,z));
		}

        public static doubleQ EulerRad(in double3 rotation)
        {
            var r = rotation * 0.5f;

            var sinx = MathX.Sin(r.x);
			var siny = MathX.Sin(r.y);
			var sinz = MathX.Sin(r.z);

			var cosx = MathX.Cos(r.x);
			var cosy = MathX.Cos(r.y);
			var cosz = MathX.Cos(r.z);

			return new doubleQ(
				cosy * sinx * cosz + siny * cosx * sinz,
				siny * cosx * cosz - cosy * sinx * sinz,
				cosy * cosx * sinz - siny * sinx * cosz,
				cosy * cosx * cosz + siny * sinx * sinz
			);
        }

		public static doubleQ Euler(in double3 rotation) => EulerRad(rotation * MathX.Deg2Rad);

        public static doubleQ DeltaRotation(in double3 angularVelocity, double deltaTime)
        {
            return DeltaRotationRad(angularVelocity * MathX.Deg2Rad, deltaTime);
        }

        public static doubleQ DeltaRotationRad(in double3 angularVelocity, double deltaTime)
        {
            var halfAngle = angularVelocity * (deltaTime * 0.5f);
            var mag = halfAngle.Magnitude;

            if(!MathX.Approximately(mag, 0))
                halfAngle *= MathX.Sin(mag) / mag;

            return new doubleQ(halfAngle.x, halfAngle.y, halfAngle.z, MathX.Cos(mag));
        }

		public static doubleQ FromToRotation(doubleQ from, doubleQ to)
		{
			return to * from.Inverted;
		}

		public static doubleQ FromToRotation(in double3 from, in double3 to)
		{
			var dot = MathX.Dot(from, to);

			if(from == to || from == double3.Zero || to == double3.Zero)
				return doubleQ.Identity;

			var cross = MathX.Cross(from, to);

			if(cross.SqrMagnitude <= 1e-8f && dot < 0f)
			{
				var temp = MathX.Cross(new double3(1,0,0), from);

				if(temp.SqrMagnitude <= 1e-8f)
					temp = MathX.Cross(new double3(0,1,0), from);
				
				return doubleQ.AxisAngleRad(temp.Normalized, MathX.PI);
			}

			return (new doubleQ(cross.x, cross.y, cross.z,
				MathX.Sqrt( from.SqrMagnitude * to.SqrMagnitude ) + dot )).Normalized;
		}
		
		
