		#region OPERATORS 

		// Unary negation
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static doubleQ operator-(in doubleQ a)
		{
			return new doubleQ(-a.x, -a.y, -a.z, -a.w);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static doubleQ operator+(in doubleQ a, in doubleQ b)
		{
			return new doubleQ(a.x+b.x, a.y+b.y, a.z+b.z, a.w+b.w);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static doubleQ operator-(in doubleQ a, in doubleQ b)
		{
			return new doubleQ(a.x-b.x, a.y-b.y, a.z-b.z, a.w-b.w);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static doubleQ operator*(in doubleQ a, in double s)
		{
			return new doubleQ(a.x*s, a.y*s, a.z*s, a.w*s);
		}

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static doubleQ operator*(in double s, in doubleQ a)
		{
			return new doubleQ(a.x*s, a.y*s, a.z*s, a.w*s);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static doubleQ operator/(in doubleQ a, in double s)
		{
			return new doubleQ(a.x/s, a.y/s, a.z/s, a.w/s);
		}

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static doubleQ operator/(in double s, in doubleQ a)
		{
			return new doubleQ(s / a.x, s / a.y, s / a.z, s / a.w);
		}

		// Quaternion multiplication
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static doubleQ operator*(in doubleQ a, in doubleQ b)
		{
            return new doubleQ(
				(a.x * b.w + b.x * a.w + a.y * b.z) - (a.z * b.y),
				(a.y * b.w + b.y * a.w + a.z * b.x) - (a.x * b.z),
				(a.z * b.w + b.z * a.w + a.x * b.y) - (a.y * b.x),
				(a.w * b.w) - (a.x * b.x + a.y * b.y + a.z * b.z));
		}

		// Rotating vector
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static double3 operator*(in doubleQ q, in double3 v)
		{
			var x = q.x + q.x;
			var y = q.y + q.y;
			var z = q.z + q.z;
			var wx = q.w * x;
			var wy = q.w * y;
			var wz = q.w * z;
			var xx = q.x * x;
			var xy = q.x * y;
			var xz = q.x * z;
			var yy = q.y * y;
			var yz = q.y * z;
			var zz = q.z * z;

			var num1 = ((1 - yy) - zz);
			var num2 = (xy - wz);
			var num3 = (xz + wy);
			var num4 = (xy + wz);
			var num5 = ((1 - xx) - zz);
			var num6 = (yz - wx);
			var num7 = (xz - wy);
			var num8 = (yz + wx);
			var num9 = ((1 - xx) - yy);

			return new double3(
				((v.x * num1) + (v.y * num2)) + (v.z * num3),
				((v.x * num4) + (v.y * num5)) + (v.z * num6),
				((v.x * num7) + (v.y * num8)) + (v.z * num9));
		}

		public static doubleQ Add(ref doubleQ a, ref doubleQ b) => a + b;
		public static doubleQ Subtract(ref doubleQ a, ref doubleQ b) => a - b;
		public static doubleQ Multiply(ref doubleQ q, double n) => q * n;
		public static doubleQ Multiply(ref doubleQ a, ref doubleQ b) => a * b;
		public static double3 Multiply(ref doubleQ q, ref double3 v) => q * v;

		#endregion

		// Conversion to/from a 4D vector (just copies components)

		[MethodImpl(MethodImplOptions.AggressiveInlining)]		
		public static explicit operator double4(in doubleQ q)
		{
			return new double4(q.x, q.y, q.z, q.w);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static explicit operator doubleQ(in double4 v)
		{
			return new doubleQ(v.x, v.y, v.z, v.w);
		}

        // Conversion to/from float/double
        			[MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static explicit operator floatQ(in doubleQ q) => new floatQ((float)q.x, (float)q.y, (float)q.z, (float)q.w);
            
		// Comparions

		public readonly bool Equals(doubleQ other) => this.x == other.x && this.y == other.y && this.z == other.z && this.w == other.w;

		public override bool Equals(object other)
		{
			if(other is doubleQ)
				return Equals((doubleQ)other);

			return false;
		}

		// These use rough comparison, which allows some small deviations

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static bool operator ==(in doubleQ a, in doubleQ b) => MathX.Approximately(a, b);

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static bool operator !=(in doubleQ a, in doubleQ b) => !(a==b);

		public override int GetHashCode()
		{
			unchecked
			{
				var hash = x.GetHashCode();
						hash = (hash*397) ^ y.GetHashCode();
						hash = (hash*397) ^ z.GetHashCode();
						hash = (hash*397) ^ w.GetHashCode();
						
				return hash;
			}
		}

