		#region OPERATIONS

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static doubleQ InvertedMultiply(in doubleQ a, in doubleQ b)
		{
            return new doubleQ(
				(-a.x * b.w + b.x * a.w - a.y * b.z) + (a.z * b.y),
				(-a.y * b.w + b.y * a.w - a.z * b.x) + (a.x * b.z),
				(-a.z * b.w + b.z * a.w - a.x * b.y) + (a.y * b.x),
				(a.w * b.w) - (-a.x * b.x - a.y * b.y - a.z * b.z));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static double3 InvertedMultiply(in doubleQ q, in double3 v)
		{
			var x = q.x + q.x;
			var y = q.y + q.y;
			var z = q.z + q.z;
			var wx = -q.w * x;
			var wy = -q.w * y;
			var wz = -q.w * z;
			var xx = q.x * x;
			var xy = q.x * y;
			var xz = q.x * z;
			var yy = q.y * y;
			var yz = q.y * z;
			var zz = q.z * z;

			var num1 = ((1 - yy) - zz);
			var num2 = (xy - wz);
			var num3 = (xz + wy);
			var num4 = (xy + wz);
			var num5 = ((1 - xx) - zz);
			var num6 = (yz - wx);
			var num7 = (xz - wy);
			var num8 = (yz + wx);
			var num9 = ((1 - xx) - yy);

			return new double3(
				((v.x * num1) + (v.y * num2)) + (v.z * num3),
				((v.x * num4) + (v.y * num5)) + (v.z * num6),
				((v.x * num7) + (v.y * num8)) + (v.z * num9));
		}

		#endregion
	}

	// Extensions

	public static partial class MathX
	{
		
			public static doubleQ Slerp(in doubleQ a, in doubleQ b, float lerp)
			{
				return Slerp(a, b, (double)lerp);
			}

			public static doubleQ Lerp(in doubleQ a, in doubleQ b, float lerp)
			{
				return Lerp(a, b, (double)lerp).FastNormalized;
			}

			
		public static doubleQ ReflectRotation(in doubleQ rotation, in double3 planeNormal)
		{
			// TODO!!! An optimized version, using Reflection Matrix?
			var forward = rotation * double3.Forward;
			var up = rotation * double3.Up;

			forward = MathX.ReflectVector(forward, planeNormal);
			up = MathX.ReflectVector(up, planeNormal);

			return doubleQ.LookRotation(forward, up);
		}

		public static double AngleAroundAxis(doubleQ rotation, double3 axis, double3? comparisonAxis = null)
		{
			double3 comparison;
			if(comparisonAxis != null)
				comparison = comparisonAxis.Value;
			else
				MathX.Orthonormals(axis, out comparison, out _);

			var rotated = rotation * comparison;

			// project both rotated and comparsion on the plane given by the axis and compute the angles they represent
			var toUp = doubleQ.FromToRotation(axis, float3.Up);

			rotated = toUp * rotated;
			comparison = toUp * comparison;

			var rotatedAngle = MathX.Atan2(rotated.xz) * MathX.Rad2Deg;
			var comparisonAngle = MathX.Atan2(comparison.xz) * MathX.Rad2Deg;

			return MathX.DeltaAngle(comparisonAngle, rotatedAngle);
		}

		// Adapted from BEPUPhysics
		public static doubleQ Slerp(in doubleQ a, doubleQ b, double lerp)
		{
			if(lerp <= 0)
				return a;
			if(lerp >= 1)
				return b;

			return SlerpUnclamped(a, b, lerp);
		}

        public static doubleQ SlerpUnclamped(in doubleQ a, doubleQ b, double lerp)
		{
			double cosHalfTheta = a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z;

            if (cosHalfTheta < 0)
            {
                b = b.Negated;
                cosHalfTheta = -cosHalfTheta;
            }

            if (cosHalfTheta >= 1)
				return b;

            var halfTheta = MathX.Acos(cosHalfTheta);
            var sinHalfTheta = MathX.Sqrt(1 - cosHalfTheta * cosHalfTheta);

            var aFraction = MathX.Sin((1 - lerp) * halfTheta) / sinHalfTheta;
            var bFraction = MathX.Sin(lerp * halfTheta) / sinHalfTheta;

			return new doubleQ(
				a.x * aFraction + b.x * bFraction,
				a.y * aFraction + b.y * bFraction,
				a.z * aFraction + b.z * bFraction,
				a.w * aFraction + b.w * bFraction
			);
		}

        public static doubleQ BezierCurve(doubleQ from, doubleQ to, doubleQ fromTangent, doubleQ toTangent, float t)
        {
            var u = 1f - t;
            var tt = t * t;
            var uu = u * u;
            var ttt = tt * t;
            var uuu = uu * u;

            return (uuu * from +
                (3 * uu * t * fromTangent) +
                (3 * u * tt * toTangent) +
                ttt * to).Normalized;
        }

        public static doubleQ BezierTangent(doubleQ from, doubleQ to, doubleQ fromTangent, doubleQ toTangent, float t)
        {
            return (-3f * MathX.Pow(1f - t, 2f) * from +
                3f * MathX.Pow(1f - t, 2f) * fromTangent -
                6f * t * (1f - t) * fromTangent -
                3f * MathX.Pow(t, 2f) * toTangent +
                6f * t * (1f - t) * toTangent +
                3f * MathX.Pow(t, 2f) * to).Normalized;
        }

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static doubleQ Lerp(in doubleQ a, in doubleQ b, double lerp)
		{
			if(lerp <= 0)
				return a;
			if(lerp >= 1)
				return b;

			return new doubleQ(a.x + (b.x - a.x) * lerp, a.y + (b.y - a.y) * lerp, a.z + (b.z - a.z) * lerp, a.w + (b.w - a.w) * lerp).FastNormalized;;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static doubleQ LerpUnclamped(in doubleQ a, in doubleQ b, double lerp)
		{
			return new doubleQ(a.x + (b.x - a.x) * lerp, a.y + (b.y - a.y) * lerp, a.z + (b.z - a.z) * lerp, a.w + (b.w - a.w) * lerp).FastNormalized;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static double Dot(in doubleQ a, in doubleQ b)
		{
			return a.x*b.x + a.y*b.y + a.z*b.z + a.w*b.w;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static double AngleRad(in doubleQ a, in doubleQ b)
		{
			return MathX.Acos(MathX.Min(MathX.Abs(Dot(a,b)), 1)) * 2;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static double Angle(in doubleQ a, in doubleQ b)
		{
			return MathX.Acos(MathX.Min(MathX.Abs(Dot(a,b)), 1)) * 2 * MathX.Rad2Deg;
		}

		public static doubleQ RotateTowards(in doubleQ from, in doubleQ to, double maxAngle)
		{
			var angle = MathX.Angle(from, to);

			if(angle == 0)
				return from;

			var ratio = MathX.Min(1, maxAngle / angle);
			return MathX.Slerp(from, to, ratio);
		}

        public static doubleQ RotateByAngle(in doubleQ from, in doubleQ to, double rotationAngle)
		{
			var angle = MathX.Angle(from, to);

			if(angle == 0)
				return from;

			var ratio = rotationAngle / angle;
			return MathX.Slerp(from, to, ratio);
		}

		public static doubleQ LimitSwing(in doubleQ rotation, in double3 axis, double maxAngle)
		{
			if(axis == double3.Zero)
				return rotation;

			var targetAxis = rotation * axis;
			var targetRotation = doubleQ.FromToRotation(axis, targetAxis);
			var limitedRotation = RotateTowards(doubleQ.Identity, targetRotation, maxAngle);
			var limitedAxis = limitedRotation * axis;

			var fix = doubleQ.FromToRotation(targetAxis, limitedAxis);

			return fix * rotation;
		}

        public static doubleQ SetSwing(in doubleQ rotation, in double3 axis, double swingAngle)
		{
			if(axis == double3.Zero)
				return rotation;

			var targetAxis = rotation * axis;
			var targetRotation = doubleQ.FromToRotation(axis, targetAxis);
			var limitedRotation = RotateByAngle(doubleQ.Identity, targetRotation, swingAngle);
			var limitedAxis = limitedRotation * axis;

			var fix = doubleQ.FromToRotation(targetAxis, limitedAxis);

			return fix * rotation;
		}

		public static doubleQ LimitTwist(in doubleQ rotation, in double3 axis, 
			in double3 orthoAxis, double maxAngle)
		{
			if(maxAngle >= 180)
				return rotation;

			maxAngle = MathX.Clamp(maxAngle, 0, 180);

			var normal = rotation * axis;
			var orthoTangent = orthoAxis;
			MathX.Orthonormalize(ref normal, ref orthoTangent);

			var rotatedOrthoTangent = rotation * orthoAxis;
			MathX.Orthonormalize(ref normal, ref rotatedOrthoTangent);

			var fixedRotation = doubleQ.FromToRotation(rotatedOrthoTangent, orthoTangent) * rotation;

			if(maxAngle == 0)
				return fixedRotation;

			return MathX.RotateTowards(fixedRotation, rotation, maxAngle);
		}

        // Based on: https://stackoverflow.com/questions/3684269/component-of-a-quaternion-rotation-around-an-axis
        public static void DecomposeSwingTwist(in doubleQ rotation, in double3 axis,
            out doubleQ swing, out doubleQ twist)
        {
            var ra = rotation.xyz;
            var p = MathX.Project(ra, axis);
            
            twist = new doubleQ(p.x, p.y, p.z, rotation.w);
            twist = twist.Normalized;

            swing = rotation * twist.Conjugated;
        }

        public static double AxisAngle(in doubleQ rotation)
        {
            return 2 * MathX.Acos(rotation.w) * MathX.Rad2Deg;
        }

        public static void DecomposeAxisAngle(in doubleQ rotation, out double3 axis, out double angle)
        {
            angle = 2 * MathX.Acos(rotation.w);
            var s = MathX.Sqrt(1-rotation.w*rotation.w);
            if(s == 0)
                axis = double3.Forward;
            else
                axis = rotation.xyz / s;

            angle *= MathX.Rad2Deg;
        }

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static doubleQ Abs(in doubleQ q)
		{
			return new doubleQ(MathX.Abs(q.x), MathX.Abs(q.y), MathX.Abs(q.z), MathX.Abs(q.w));
		}

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static doubleQ Pow(in doubleQ q, double pow)
        {
            var angle = MathX.Acos(MathX.Clamp(q.w, -1, 1));
            var sinAngle = MathX.Sin(angle);

            if(MathX.Approximately(sinAngle, 0))
                return q;

            var unitVector = q.xyz / sinAngle;

            var newAngle = angle * pow;

            var newW = MathX.Cos(newAngle);
            var newV = unitVector * MathX.Sin(newAngle);

            return new doubleQ(newV.x, newV.y, newV.z, newW);
        }

