	public static class DoubleQExtensions
	{
		public static void Write(this BinaryWriter wr, in doubleQ q)
		{
			wr.Write(q.x);
			wr.Write(q.y);
			wr.Write(q.z);
			wr.Write(q.w);
		}

		public static doubleQ ReadDoubleQ(this BinaryReader rd)
		{
			return new doubleQ(
				rd.ReadDouble(),
				rd.ReadDouble(),
				rd.ReadDouble(),
				rd.ReadDouble()
			);
		}
	}

	
